const canvas=document.getElementById('bodyCanvas'),ctx=canvas.getContext('2d');
const baseVitals={heart:72,temp:36.8,oxygen:98,systolic:118,diastolic:76,glucose:91,resp:14,hydration:100,stress:12};
let vitals={...baseVitals},layers={skin:false,muscle:true,vascular:true,organs:true,skeleton:false,nervous:false,cells:false},view='systems',playing=false,seconds=0,speed=1,ingredients=[],condition='healthy',trial=0,trialEffects={},strength=50,windowMinutes=2;
function resize(){const r=canvas.getBoundingClientRect(),d=devicePixelRatio||1;canvas.width=r.width*d;canvas.height=r.height*d;ctx.setTransform(d,0,0,d,0,0)}window.addEventListener('resize',resize);resize();
function path(points,color,width=1,alpha=1){ctx.save();ctx.globalAlpha=alpha;ctx.strokeStyle=color;ctx.lineWidth=width;ctx.lineJoin='round';ctx.lineCap='round';ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.stroke();ctx.restore()}
function ellipse(x,y,rx,ry,fill,stroke,rot=0){ctx.beginPath();ctx.ellipse(x,y,rx,ry,rot,0,Math.PI*2);ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke()}}
function drawBody(){const w=canvas.clientWidth,h=canvas.clientHeight,cx=w/2,sc=Math.min(w/440,h/600),pulse=1+Math.sin(seconds*4)*.025;ctx.clearRect(0,0,w,h);ctx.save();ctx.translate(cx,17);ctx.scale(sc,sc);
 const glow=ctx.createRadialGradient(0,285,30,0,285,235);glow.addColorStop(0,'#1a3b42');glow.addColorStop(1,'#0a171c');ellipse(0,293,225,290,glow);
